def min_flips(binary_string):
    # Chaguo la kwanza: mfuatano unaanza na 0
    flips_0 = 0
    for i in range(len(binary_string)):
        if i % 2 == 0 and binary_string[i] != '0':
            flips_0 += 1
        elif i % 2 != 0 and binary_string[i] != '1':
            flips_0 += 1

    # Chaguo la pili: mfuatano unaanza na 1
    flips_1 = 0
    for i in range(len(binary_string)):
        if i % 2 == 0 and binary_string[i] != '1':
            flips_1 += 1
        elif i % 2 != 0 and binary_string[i] != '0':
            flips_1 += 1

    # Chaguo la mfuatano unaohitaji idadi ndogo ya mabadiliko
    return min(flips_0, flips_1)
```

